import React from 'react';
import {C, F, D} from '../../kit/theme';
import {ep} from '../../kit/anim';
import {VBig, VCmd, VLabel, VNote, VPanel, VStrip} from '../../kit/V';
import type {SceneProps} from '../../kit/Episode';

/* Every number on screen comes from the E block below, generated from the two evidence files of the fl08 fixture
   (episodes/fl08/fixture/gen-facts.mjs): evidence.json is ffmpeg 6.1.1, evidence-v8.json is ffmpeg 8.1.2.
   Vertical 1080x1920: scenes draw in x 60..940, y 220..1360 (the caption bar owns y 1380..1500). */
// E:start (generated by episodes/fl08/fixture/gen-facts.mjs from evidence.json and evidence-v8.json; do not edit by hand)
const E: any = { "version6": "6.1.1", "version8": "8.1.2", "ramp": { "width": 256, "height": 16, "frames": 3 }, "tag6": { "none": "unknown", "tv": "tv", "pc": "pc" }, "tag8": { "none": "tv", "tv": "tv" }, "full": [ 0, 255 ], "limited": [ 16, 235 ], "mid": [ 64, 191 ], "rgb": { "limitedTv": { "min": 0, "max": 255 }, "limitedPc": { "min": 16, "max": 235 }, "fullTv": { "levels": 220, "black": 17, "white": 21 }, "fullPc": { "levels": 256 }, "midTv": { "min": 55, "max": 203 }, "midPc": { "min": 64, "max": 191 }, "untaggedSameAsTv": true, "tv8": { "levels": 220, "black": 17, "white": 21 } }, "opt": { "v6": { "limited": [ 16, 235 ], "mid": [ 64, 191 ] }, "v8": { "limited": [ 0, 255 ], "mid": [ 56, 204 ], "tag": "pc" } }, "vf": { "v6": { "full": [ 0, 255 ], "limited": [ 16, 235 ], "mid": [ 64, 191 ], "tag": "pc" }, "v8": { "full": [ 16, 235 ], "limited": [ 30, 218 ], "mid": [ 71, 180 ], "tag": "tv" } }, "label8": { "full": [ 0, 255 ], "limited": [ 16, 235 ], "mid": [ 64, 191 ], "tag": "pc" }, "missing": { "status": 8, "message": "No such filter: 'colordetect'", "libavfilter6": "9.12.100" }, "recipe": { "full": [ 0, 255 ], "limited": [ 16, 235 ], "hiMax": 236, "hiPerFrame": [ [ 16, 235 ], [ 16, 235 ], [ 16, 236 ] ], "loPerFrame": [ [ 15, 235 ], [ 16, 235 ], [ 16, 235 ] ], "hiFrames": 1, "frames": 3, "loMin": 15, "edge": [ 16, 235 ], "cbMax": 254, "verdicts": { "full": "full", "limited": "undetermined", "mid": "undetermined", "hi1": "full", "lo1": "full", "edge": "undetermined", "cbLuma": "undetermined", "cbChroma": "full" } }, "cd": { "full": { "rangeText": "JPEG / full range", "range": "full" }, "limited": { "rangeText": "undetermined", "range": "undetermined" }, "mid": { "rangeText": "undetermined", "range": "undetermined" }, "hi1": { "rangeText": "JPEG / full range", "range": "full" }, "lo1": { "rangeText": "JPEG / full range", "range": "full" }, "edge": { "rangeText": "undetermined", "range": "undetermined" }, "cb": { "rangeText": "undetermined", "range": "undetermined" }, "fullNone": { "rangeText": "JPEG / full range", "range": "full" }, "optLimited": { "rangeText": "JPEG / full range", "range": "full" }, "optMid": { "rangeText": "undetermined", "range": "undetermined" }, "noAlphaPlane": "none", "blocks": 1, "modeRangeOnlyAlpha": null, "modeAlphaOnlyRange": null, "help": true }, "alpha": { "opaque": { "px": [ 255, 0, 0, 255 ], "cd": "opaque" }, "straight": { "px": [ 255, 0, 0, 128 ], "cd": "straight", "yuva": "undetermined" }, "premult": { "px": [ 128, 0, 0, 128 ], "cd": "undetermined" }, "dark": { "px": [ 64, 0, 0, 128 ], "cd": "undetermined" }, "zero": { "px": [ 0, 0, 0, 0 ], "cd": "undetermined" }, "boundary": { "px": [ 128, 0, 0, 127 ], "cd": "straight" }, "bad": { "frames": 3, "cd": "straight", "pixels": 3072, "evidence": 1 }, "rampStraightYuva": "straight", "redLavfi": [ 255, 0, 0, 127 ], "files": { "identical": true, "pix_fmt": "bgra", "keys": 0 } }, "trace": { "metadataKeys": 0, "sideData": null, "tagAfter": "tv" } };
// E:end

const rv = (t: number, dur: number, a: number, b: number) => ep(t, a * dur, b * dur);
const gray = (v: number) => `rgb(${v},${v},${v})`;
const VERDICT_COLOR: Record<string, string> = {full: C.green, opaque: C.green, straight: C.green, undetermined: C.amber, limited: C.red};

/* ------------------------------------------------------------------ local drawing helpers */

const X0 = 60;
const WD = 880;

/** A value scale 0..255 with the limited band 16..235 shaded; the solid span is where the values are, the dashed ghost where they were. */
const VRange: React.FC<{y: number; label: string; lo: number; hi: number; ghost?: number[]; band?: number[]; color?: string; note?: string; noteColor?: string; ticks?: boolean; p?: number; o?: number; x?: number; w?: number}> = ({y, label, lo, hi, ghost, band = [16, 235], color = C.cyan, note, noteColor, ticks = false, p = 1, o = 1, x = X0, w = WD}) => {
  const px = (v: number) => x + (v / 255) * w;
  const bw = Math.max(10, (px(hi) - px(lo)) * p);
  return (
    <div style={{position: 'absolute', left: 0, top: y, width: 1080, height: 150, opacity: o, fontFamily: F.sans}}>
      <div style={{position: 'absolute', left: x, top: 0, width: w, display: 'flex', justifyContent: 'space-between', alignItems: 'baseline'}}>
        <span style={{fontSize: 32, fontWeight: 700, color: C.text}}>{label}</span>
        {note && <span style={{fontSize: 32, fontWeight: 800, color: noteColor ?? color}}>{note}</span>}
      </div>
      <div style={{position: 'absolute', left: x, top: 50, width: w, height: 64, borderRadius: 12, background: C.panel, border: `2px solid ${C.line}`, boxSizing: 'border-box'}} />
      <div style={{position: 'absolute', left: px(band[0]), top: 44, width: px(band[1]) - px(band[0]), height: 76, border: `2px dashed ${C.mute}`, borderRadius: 8, boxSizing: 'border-box', background: `${C.amber}14`}} />
      {ghost && <div style={{position: 'absolute', left: px(ghost[0]), top: 58, width: px(ghost[1]) - px(ghost[0]), height: 48, borderRadius: 8, border: `3px dashed ${C.dim}`, boxSizing: 'border-box'}} />}
      <div style={{position: 'absolute', left: px(lo), top: 58, width: bw, height: 48, borderRadius: 8, background: color, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: F.mono, fontWeight: 700, fontSize: 28, color: C.bg, whiteSpace: 'nowrap', overflow: 'hidden'}}>{p > 0.8 ? `${lo}..${hi}` : ''}</div>
      {ticks && [0, band[0], band[1], 255].map((v, i) => (
        <div key={i} style={{position: 'absolute', left: px(v) - 40, top: 122, width: 80, textAlign: 'center', fontFamily: F.mono, fontSize: 24, color: C.dim}}>{v}</div>
      ))}
    </div>
  );
};

const Chip: React.FC<{x: number; y: number; w: number; text: string; color: string; o?: number; size?: number}> = ({x, y, w, text, color, o = 1, size = 32}) => (
  <div style={{position: 'absolute', left: x, top: y, width: w, height: 64, opacity: o, boxSizing: 'border-box', borderRadius: 32, border: `3px solid ${color}`, background: `${color}22`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: F.sans, fontSize: size, fontWeight: 800, color: C.text, whiteSpace: 'nowrap'}}>{text}</div>
);

const Swatch: React.FC<{x: number; y: number; s?: number; rgba: number[]; o?: number}> = ({x, y, s = 120, rgba, o = 1}) => (
  <div style={{position: 'absolute', left: x, top: y, width: s, height: s, opacity: o, borderRadius: 14, border: `3px solid ${C.line}`, boxSizing: 'border-box', overflow: 'hidden', background: `conic-gradient(${C.bg2} 25%, ${C.line} 0 50%, ${C.bg2} 0 75%, ${C.line} 0) 0 0 / 36px 36px`}}>
    <div style={{position: 'absolute', inset: 0, background: `rgba(${rgba[0]},${rgba[1]},${rgba[2]},${rgba[3] / 255})`}} />
  </div>
);

const Log: React.FC<{x?: number; y: number; w?: number; lines: {text: string; color?: string; bold?: boolean}[]; color?: string; o?: number; size?: number}> = ({x = X0, y, w = WD, lines, color = C.green, o = 1, size = 32}) => (
  <div style={{position: 'absolute', left: x, top: y, width: w, opacity: o, boxSizing: 'border-box', borderRadius: 18, background: C.codeBg, border: `3px solid ${color}`, padding: '20px 28px', fontFamily: F.mono, fontSize: size, lineHeight: 1.45, color: C.text}}>
    {lines.map((l, i) => <div key={i} style={{whiteSpace: 'pre', color: l.color ?? C.text, fontWeight: l.bold ? 700 : 400}}>{l.text}</div>)}
  </div>
);

/* ------------------------------------------------------------------ scenes */

/* 1. hook */
const Hook: React.FC<SceneProps> = ({t, dur}) => {
  const U = WD / 256; // px per column
  const b = E.rgb.fullTv.black, w = E.rgb.fullTv.white;
  return (
    <>
      <VLabel kind="over" text="A 0..255 gray ramp, tagged tv" y={230} color={C.amber} o={rv(t, dur, 0.02, 0.1)} />
      <VBig y={285} h={400} value={`${E.rgb.fullTv.levels} of 256`} sub="levels survive the conversion to RGB" color={C.text} accent={C.red} o={rv(t, dur, 0.08, 0.22)} />
      <div style={{position: 'absolute', left: X0, top: 730, fontFamily: F.sans, fontSize: 30, fontWeight: 700, color: C.dim, opacity: rv(t, dur, 0.3, 0.4)}}>the file</div>
      <div style={{position: 'absolute', left: X0, top: 775, width: WD, height: 84, borderRadius: 10, background: `linear-gradient(to right, ${gray(0)}, ${gray(255)})`, border: `3px solid ${C.line}`, boxSizing: 'border-box', opacity: rv(t, dur, 0.3, 0.4)}} />
      <div style={{position: 'absolute', left: X0, top: 905, fontFamily: F.sans, fontSize: 30, fontWeight: 700, color: C.dim, opacity: rv(t, dur, 0.45, 0.55)}}>shown as RGB</div>
      <div style={{position: 'absolute', left: X0, top: 950, width: WD, height: 84, display: 'flex', borderRadius: 10, overflow: 'hidden', border: `3px solid ${C.line}`, boxSizing: 'border-box', opacity: rv(t, dur, 0.45, 0.55)}}>
        <div style={{width: b * U, background: gray(0), flexShrink: 0}} />
        <div style={{flex: 1, background: `linear-gradient(to right, ${gray(0)}, ${gray(255)})`}} />
        <div style={{width: w * U, background: gray(255), flexShrink: 0}} />
      </div>
      <div style={{position: 'absolute', left: X0, top: 1050, fontFamily: F.mono, fontSize: 32, fontWeight: 700, color: C.red, opacity: rv(t, dur, 0.6, 0.7)}}>{b} columns: black</div>
      <div style={{position: 'absolute', left: X0, top: 1100, fontFamily: F.mono, fontSize: 32, fontWeight: 700, color: C.red, opacity: rv(t, dur, 0.68, 0.78)}}>{w} columns: white</div>
    </>
  );
};

/* 2. tag */
const Tag: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text="The tag is a label" y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VCmd y={285} h={170} maxLines={3} text={`ffmpeg -i ramp.mkv -vf setparams=range=${E.tag6.pc} -color_range ${E.tag6.pc} out.mkv`} hi={`range=${E.tag6.pc} -color_range ${E.tag6.pc}`} size={32} o={rv(t, dur, 0.05, 0.16)} />
    <VRange y={470} label={`No tag (${E.version6}: ${E.tag6.none})`} lo={E.limited[0]} hi={E.limited[1]} color={C.dim} ticks p={rv(t, dur, 0.2, 0.34)} o={rv(t, dur, 0.18, 0.26)} />
    <VRange y={680} label={`Tagged ${E.tag6.tv}`} lo={E.limited[0]} hi={E.limited[1]} color={C.cyan} p={rv(t, dur, 0.38, 0.52)} o={rv(t, dur, 0.36, 0.44)} />
    <VRange y={850} label={`Tagged ${E.tag6.pc}`} lo={E.limited[0]} hi={E.limited[1]} color={C.amber} p={rv(t, dur, 0.55, 0.7)} o={rv(t, dur, 0.53, 0.61)} />
    <VNote y={1050} h={190} tone="ok" tag="Same bytes" text="Three tags, one set of pixels. ffprobe reports the label only." size={36} o={rv(t, dur, 0.75, 0.88)} />
  </>
);

/* 3. consequence */
const Consequence: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text="Same bytes, converted to RGB" y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VRange y={290} label="In the file" lo={E.limited[0]} hi={E.limited[1]} color={C.dim} ticks p={rv(t, dur, 0.1, 0.25)} o={rv(t, dur, 0.08, 0.16)} />
    <VRange y={540} label="Tagged tv, shown as" lo={E.rgb.limitedTv.min} hi={E.rgb.limitedTv.max} ghost={E.limited} color={C.red} note="stretched" p={rv(t, dur, 0.3, 0.5)} o={rv(t, dur, 0.28, 0.36)} />
    <VRange y={760} label="Tagged pc, shown as" lo={E.rgb.limitedPc.min} hi={E.rgb.limitedPc.max} color={C.green} note="as is" p={rv(t, dur, 0.52, 0.7)} o={rv(t, dur, 0.5, 0.58)} />
    <VNote y={990} h={190} tone="doubt" tag="No tag" text={`Shown as tv, on ${E.version6} and ${E.version8}.`} size={38} o={rv(t, dur, 0.75, 0.88)} />
  </>
);

/* 4. option */
const Option: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text="Same flag, two builds" y={230} color={C.amber} o={rv(t, dur, 0.02, 0.1)} />
    <VCmd y={285} text="ffmpeg -i ramp.yuv -color_range pc out.mkv" hi="-color_range pc" size={34} o={rv(t, dur, 0.05, 0.16)} />
    <VPanel y={460} h={420} color={C.green} o={rv(t, dur, 0.2, 0.4)}>
      <VLabel kind="over" text={`ffmpeg ${E.version6}: relabel`} y={28} x={30} w={820} color={C.green} />
    </VPanel>
    <VRange y={530} label="Limited ramp after" lo={E.opt.v6.limited[0]} hi={E.opt.v6.limited[1]} ghost={E.limited} color={C.green} note={`tag ${E.tag6.pc}`} x={90} w={800} p={rv(t, dur, 0.28, 0.42)} o={rv(t, dur, 0.26, 0.34)} />
    <VRange y={690} label="Mid ramp after" lo={E.opt.v6.mid[0]} hi={E.opt.v6.mid[1]} ghost={E.mid} color={C.green} x={90} w={800} p={rv(t, dur, 0.34, 0.46)} o={rv(t, dur, 0.32, 0.4)} />
    <VPanel y={920} h={420} color={C.red} o={rv(t, dur, 0.5, 0.7)}>
      <VLabel kind="over" text={`ffmpeg ${E.version8}: convert`} y={28} x={30} w={820} color={C.red} />
    </VPanel>
    <VRange y={990} label="Limited ramp after" lo={E.opt.v8.limited[0]} hi={E.opt.v8.limited[1]} ghost={E.limited} color={C.red} note={`tag ${E.opt.v8.tag}`} x={90} w={800} p={rv(t, dur, 0.58, 0.72)} o={rv(t, dur, 0.56, 0.64)} />
    <VRange y={1150} label="Mid ramp after" lo={E.opt.v8.mid[0]} hi={E.opt.v8.mid[1]} ghost={E.mid} color={C.red} x={90} w={800} p={rv(t, dur, 0.64, 0.76)} o={rv(t, dur, 0.62, 0.7)} />
  </>
);

/* 5. missing */
const Missing: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text={`ffmpeg ${E.version6}`} y={230} color={C.red} o={rv(t, dur, 0.02, 0.1)} />
    <VCmd y={280} h={130} text="ffmpeg -i in.mkv -vf colordetect -f null -" hi="colordetect" color={C.red} size={28} maxLines={2} o={rv(t, dur, 0.05, 0.15)} />
    <VNote y={440} h={120} tone="fail" text={`${E.missing.message}  exit code ${E.missing.status}`} size={34} maxLines={2} o={rv(t, dur, 0.15, 0.28)} />
    <VCmd y={600} h={190} text="ffmpeg -i in.mkv -vf signalstats,metadata=mode=print:file=- -f null -" hi="signalstats" color={C.cyan} size={30} maxLines={3} o={rv(t, dur, 0.3, 0.42)} />
    <VLabel kind="over" text="Y max per frame" y={830} color={C.dim} o={rv(t, dur, 0.45, 0.55)} />
    <VStrip y={875} h={190} n={3} cur={E.recipe.hiPerFrame.findIndex((f: number[]) => f[1] > 235)} label={(i) => String(E.recipe.hiPerFrame[i][1])} color={C.red} o={rv(t, dur, 0.5, 0.68)} />
    <VNote y={1110} h={170} tone="ok" text={`Above 235 in ${E.recipe.hiFrames} frame of ${E.recipe.frames}: full range, proven.`} size={36} o={rv(t, dur, 0.75, 0.9)} />
  </>
);

/* 6. full */
const Full: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text={`colordetect on ${E.version8}`} y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VCmd y={280} h={160} text="ffmpeg -v info -i ramp.mkv -vf colordetect=mode=all -f null -" hi="colordetect" size={32} maxLines={3} o={rv(t, dur, 0.05, 0.16)} />
    <VRange y={500} label="The pixels" lo={E.full[0]} hi={E.full[1]} color={C.green} ticks p={rv(t, dur, 0.2, 0.4)} o={rv(t, dur, 0.18, 0.26)} />
    <Log y={720} lines={[{text: 'Detected color properties:', color: C.dim}, {text: `  Color range: ${E.cd.full.rangeText}`, bold: true, color: C.green}]} size={32} o={rv(t, dur, 0.45, 0.62)} />
    <Chip x={X0} y={940} w={420} text="tagged tv: full" color={C.green} o={rv(t, dur, 0.65, 0.75)} />
    <Chip x={520} y={940} w={420} text={`no tag: ${E.cd.fullNone.range}`} color={C.green} o={rv(t, dur, 0.75, 0.85)} />
  </>
);

/* 7. limited */
const Limited: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text={`colordetect on ${E.version8}`} y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VRange y={290} label="Limited ramp" lo={E.limited[0]} hi={E.limited[1]} color={C.amber} ticks note={E.cd.limited.rangeText} p={rv(t, dur, 0.1, 0.25)} o={rv(t, dur, 0.08, 0.16)} />
    <VRange y={520} label="Mid ramp" lo={E.mid[0]} hi={E.mid[1]} color={C.amber} note={E.cd.mid.rangeText} p={rv(t, dur, 0.28, 0.43)} o={rv(t, dur, 0.26, 0.34)} />
    <VRange y={730} label="Only 16 and 235" lo={E.recipe.edge[0]} hi={E.recipe.edge[1]} color={C.amber} note={E.cd.edge.rangeText} p={rv(t, dur, 0.46, 0.6)} o={rv(t, dur, 0.44, 0.52)} />
    <VNote y={960} h={160} tone="fail" tag="Never limited" text="Any clip, any tag, any mode." size={38} o={rv(t, dur, 0.66, 0.78)} />
    <VNote y={1150} h={160} tone="doubt" text="A full range file can hold the same pixels." size={36} o={rv(t, dur, 0.8, 0.92)} />
  </>
);

/* 8. luma */
const Luma: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text="What it does not look at" y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VRange y={290} label="Y (luma)" lo={E.limited[0]} hi={E.limited[1]} color={C.green} ticks note="inside" p={rv(t, dur, 0.12, 0.28)} o={rv(t, dur, 0.1, 0.18)} />
    <VRange y={540} label="Cb (chroma)" lo={0} hi={E.recipe.cbMax} band={[16, 240]} color={C.red} note="outside" p={rv(t, dur, 0.3, 0.48)} o={rv(t, dur, 0.28, 0.36)} />
    <VNote y={800} h={170} tone="doubt" tag="colordetect" text={`${E.cd.cb.range}: luma decides`} size={40} o={rv(t, dur, 0.55, 0.7)} />
    <VNote y={1010} h={170} tone="ok" tag="Recipe with chroma" text={`${E.recipe.verdicts.cbChroma}: any plane outside`} size={40} o={rv(t, dur, 0.7, 0.85)} />
  </>
);

/* 9. notecho */
const NotEcho: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text={`Both tagged ${E.opt.v8.tag} (-color_range)`} y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VPanel y={290} h={500} color={C.green} o={rv(t, dur, 0.1, 0.3)} />
    <VRange y={330} label="Limited ramp, converted" lo={E.opt.v8.limited[0]} hi={E.opt.v8.limited[1]} ghost={E.limited} color={C.green} x={90} w={800} p={rv(t, dur, 0.2, 0.36)} o={rv(t, dur, 0.18, 0.28)} />
    <Chip x={140} y={560} w={760} text={`colordetect: ${E.cd.optLimited.range}`} color={C.green} size={36} o={rv(t, dur, 0.38, 0.5)} />
    <VPanel y={840} h={500} color={C.amber} o={rv(t, dur, 0.5, 0.7)} />
    <VRange y={880} label="Mid ramp, converted" lo={E.opt.v8.mid[0]} hi={E.opt.v8.mid[1]} ghost={E.mid} color={C.amber} x={90} w={800} p={rv(t, dur, 0.6, 0.76)} o={rv(t, dur, 0.58, 0.68)} />
    <Chip x={140} y={1110} w={760} text={`colordetect: ${E.cd.optMid.range}`} color={C.amber} size={36} o={rv(t, dur, 0.78, 0.9)} />
  </>
);

/* 10. alpha */
const Alpha: React.FC<SceneProps> = ({t, dur}) => {
  const cards = [
    {k: 'opaque', rgba: E.alpha.opaque.px, v: E.alpha.opaque.cd},
    {k: 'straight', rgba: E.alpha.straight.px, v: E.alpha.straight.cd},
    {k: 'premult-looking', rgba: E.alpha.premult.px, v: E.alpha.premult.cd},
    {k: 'all zero', rgba: E.alpha.zero.px, v: E.alpha.zero.cd},
  ];
  const cw = 420, ch = 330;
  return (
    <>
      <VLabel kind="over" text={`Alpha mode, colordetect ${E.version8}`} y={230} o={rv(t, dur, 0.02, 0.1)} />
      {cards.map((c, i) => {
        const x = X0 + (i % 2) * (cw + 40), y = 290 + Math.floor(i / 2) * (ch + 30), o = rv(t, dur, 0.1 + i * 0.12, 0.22 + i * 0.12), col = VERDICT_COLOR[c.v] ?? C.dim;
        return (
          <React.Fragment key={c.k}>
            <VPanel x={x} y={y} w={cw} h={ch} color={col} o={o} />
            <Swatch x={x + 24} y={y + 28} rgba={c.rgba} o={o} />
            <div style={{position: 'absolute', left: x + 164, top: y + 36, width: cw - 180, fontFamily: F.mono, fontSize: 26, color: C.dim, lineHeight: 1.3, opacity: o}}>{c.rgba.join(',')}</div>
            <div style={{position: 'absolute', left: x + 164, top: y + 98, width: cw - 180, fontFamily: F.sans, fontSize: 28, fontWeight: 700, color: C.text, lineHeight: 1.15, opacity: o}}>{c.k}</div>
            <Chip x={x + 24} y={y + 214} w={cw - 48} text={c.v} color={col} o={o} size={32} />
          </React.Fragment>
        );
      })}
      <VNote y={1030} h={200} tone="ok" tag="One bad pixel" text={`In 1 of ${E.alpha.bad.frames} frames: ${E.alpha.bad.cd}.`} size={38} o={rv(t, dur, 0.7, 0.85)} />
    </>
  );
};

/* 11. close */
const Close: React.FC<SceneProps> = ({t, dur}) => (
  <>
    <VLabel kind="over" text={`Measured on ${E.version6} and ${E.version8}`} y={230} o={rv(t, dur, 0.02, 0.1)} />
    <VLabel kind="head" text="The label is not the pixels." y={285} color={C.text} o={rv(t, dur, 0.05, 0.16)} />
    <VNote y={620} h={130} tone="info" tag="ffprobe" text="tells you the label" size={38} o={rv(t, dur, 0.2, 0.34)} />
    <VNote y={790} h={130} tone="ok" tag="signalstats, colordetect" text="can prove full range" size={38} o={rv(t, dur, 0.38, 0.52)} />
    <VNote y={960} h={130} tone="fail" tag="Nothing" text="can prove limited" size={38} o={rv(t, dur, 0.56, 0.7)} />
    <VNote y={1130} h={190} tone="doubt" tag="Not tested" text="Real footage, lossy codecs, players." size={36} o={rv(t, dur, 0.74, 0.88)} />
  </>
);

export const scenes: Record<string, React.FC<SceneProps>> = {
  hook: Hook, tag: Tag, consequence: Consequence, option: Option, missing: Missing, full: Full, limited: Limited, luma: Luma, notecho: NotEcho, alpha: Alpha, close: Close,
};
